        : '';

      const voiceNotes = Array.isArray(task.voiceNotes) ? task.voiceNotes : [];
      const voiceHtml = voiceNotes.length
        ? `
          <div class="card-voice-notes">
            <div class="subtasks-header">Voice Notes (${voiceNotes.length})</div>
